import type { EditorPlugin, EditorPluginOptions, ViewerPlugin } from './../ricos-types/index.js';

type PluginType = EditorPlugin | ViewerPlugin | EditorPluginOptions;

export const extractPluginsConfig = (plugins: PluginType[] | undefined) => {
  let mergedConfig: Record<string, Record<string, any>> = {};
  plugins?.forEach(plugin => {
    const { type, ...rest } = plugin;
    const config = 'config' in plugin ? plugin.config : rest;
    if (config && Object.keys(config).length !== 0) {
      mergedConfig = { ...mergedConfig, [type]: config };
    }
  });
  return { config: mergedConfig };
};
