import { sdk } from '@wix/image-kit';

import type { ImageData_Crop } from './../../ricos-schema/next-schema/index.js';

import { toPixelCrop } from './image-crop.js';

export const getCroppedImage = ({
  mediaId,
  sourceWidth,
  sourceHeight,
  crop,
}: {
  mediaId: string | undefined;
  sourceWidth: number | undefined;
  sourceHeight: number | undefined;
  crop?: ImageData_Crop | null;
}) => {
  const pixelCrop = toPixelCrop({ crop, sourceWidth, sourceHeight });

  if (!mediaId || !sourceWidth || !sourceHeight || !pixelCrop) {
    return;
  }

  return {
    url: sdk.getCropImageURL(
      mediaId,
      sourceWidth,
      sourceHeight,
      pixelCrop.x,
      pixelCrop.y,
      pixelCrop.width,
      pixelCrop.height,
      pixelCrop.width,
      pixelCrop.height
    ),
    width: pixelCrop.width,
    height: pixelCrop.height,
  };
};
