import type { Node } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as RicosDocumentNode } from './../../ricos-schema/next-schema/index.js';

import { getNodeAnimation } from './get-node-animation.js';
import { hasEntranceAnimation } from './has-entrance-animation.js';

/**
 * The reveal-contract attributes for nodes that must render them on their own DOM
 * element rather than through the generic AnimationDecorator wrapper. Today that
 * is LIST_ITEM alone (a div between `<ul>` and `<li>` is invalid HTML) — it must
 * stay in sync with `SELF_ANIMATED_TYPES` in the decorator, including the
 * entrance-only `data-ricos-entrance` hide marker.
 *
 * Callers are still responsible for the `pluginAnimationViewer` gate — the hide CSS is
 * scoped to its own viewer instance (node-animations.tsx), so an ungated attribute no
 * longer risks another viewer hiding the node, but it is dead markup either way.
 */
export const getAnimationDomAttrs = (
  node: Node | RicosDocumentNode
): { 'data-ricos-animation'?: string; 'data-ricos-entrance'?: string } => {
  const animation = getNodeAnimation(node as RicosDocumentNode);
  if (!animation || !node.id) {
    return {};
  }
  return {
    'data-ricos-animation': node.id,
    ...(hasEntranceAnimation(animation) ? { 'data-ricos-entrance': '' } : {}),
  };
};
